# RM 2018 · Neumotórax a tensión: descompresión con angiocatéter · 17 MONITOR con signos vitales
S("monitor", "RM-CIR-EJ2", "Atropellado con disnea marcada, PA 80/50, SatO₂ 85 %, tráquea desviada y murmullo vesicular ausente en el hemitórax izquierdo: neumotórax a tensión, descompresión inmediata con aguja o angiocatéter",
  "Trauma torácico · neumotórax a tensión",
  ("Neumotórax a tensión", ["El aire entra al espacio pleural y no sale (válvula): colapsa el pulmón, empuja el mediastino y comprime las venas.",
                            "Cae el retorno venoso: shock obstructivo con tráquea desviada hacia el lado contrario."]),
  ("Varón de 25 años, atropellado", ["Disnea marcada, sudoración, extremidades frías.", "PA 80/50, FR 28, SatO₂ 85 %, tráquea desviada y sin murmullo vesicular izquierdo."]),
  ["Es un diagnóstico clínico: NO esperar la radiografía.",
   "Descompresión inmediata con catéter 14 G: 5.º espacio intercostal, línea axilar anterior (ATLS), o 2.º espacio, línea medioclavicular; en el lado izquierdo se prefiere el 2.º por el riesgo de lesión cardíaca.",
   "Las agujas más largas fallan menos (−7,8 % por cada cm; unos 7 cm); si no alcanza, toracostomía con dedo o con tubo. Después, tubo de tórax: es el tratamiento definitivo."],
  ATLS + ", neumotórax a tensión; World J Emerg Surg 2025, metaanálisis de longitud de aguja y sitio de descompresión (PMID 40383767); ESC/ETC (European Trauma Course).",
  op=("¿Procedimiento inmediato?", ["No: no existe en el trauma torácico", "Sí: alivia la tensión en segundos", "No: el drenaje laminar no sirve en neumotórax",
                                    "No: la presión positiva aumenta la tensión", "No: es una medida extrema, no la inicial"],
      {1: "Descompresión con angiocatéter", 2: "Toracotomía mínima con drenaje laminar", 4: "Toracotomía a cielo abierto"}),
  d=dict(rotulo="Los signos vitales del caso", titulo_monitor="MONITOR · TRAUMA",
         valores=[("PA", "80/50", "mmHg", "bajo"), ("SatO₂", "85", "%", "bajo"), ("FR", "28", "rpm", "alto"),
                  ("TRÁQUEA", "desviada", "", "alto"), ("MV IZQ.", "ausente", "", "bajo"), ("PIEL", "fría, sudada", "", "alto")],
         lectura=[("Shock + hipoxemia + MV ausente", "Neumotórax a tensión: es clínico, no esperar la radiografía.", True),
                  ("Tráquea desviada al lado sano", "El mediastino es empujado por el aire a presión.", True),
                  ("Primero descomprimir", "Catéter 14 G largo (≈ 7 cm); en el lado izquierdo, 2.º espacio en la línea medioclavicular.", True),
                  ("Después", "Tubo de tórax conectado a sello de agua; reevaluar con la secuencia ABCDE.", False)],
         veredicto=("Neumotórax a tensión con shock = descompresión inmediata con catéter", "Luego, tubo de drenaje torácico: es el tratamiento definitivo."))
  )

# RM 2018 · RN con FC 60 y apnea: ventilación con bolsa y máscara · 13 RELOJ
S("reloj", "RM-PED-EJ3", "Recién nacido a término con frecuencia cardíaca de 60 por minuto y sin respiración espontánea: ventilación con presión positiva con bolsa y máscara",
  "Neonatología · reanimación neonatal",
  ("Reanimación neonatal", ["En el recién nacido el problema casi siempre es el pulmón, no el corazón: lo primero es ventilar.",
                            "Cada paso se decide por la frecuencia cardíaca y la respiración, en ciclos de 30 segundos."]),
  ("Recién nacido a término", ["Sin respiración espontánea.", "Frecuencia cardíaca de 60 por minuto."]),
  ["Pasos iniciales: calor, secar, estimular, posición de la vía aérea. Si hay apnea, jadeo (gasping) o FC < 100: ventilación a presión positiva.",
   "Tras 30 s de ventilación eficaz (el tórax sube) con FC < 60: compresiones 3:1 e intubación, con FiO₂ 100 %.",
   "Si sigue < 60 después de 60 s de compresiones: adrenalina IV (0,01-0,03 mg/kg) y vía umbilical."],
  "AHA/AAP, reanimación neonatal, actualización 2025 (Trop Doct 2026, PMID 42599690; Arch Argent Pediatr 2026, PMID 42578581); MINSA, NTS N.º 214-MINSA/DGIESP-2024, atención integral de salud neonatal (RM 545-2024/MINSA); " + NELSON + ".",
  op=("¿Qué hacer?", ["No: el oxígeno pasivo no ventila a un recién nacido apneico", "No: no hay esfuerzo respiratorio que la cánula ayude",
                      "No: necesita respiración activa, no solo presión continua", "No: primero se prueba la bolsa y la máscara",
                      "Sí: apnea + FC < 100 = ventilación con presión positiva"],
      {0: "Oxígeno con máscara de reservorio", 1: "Oxígeno con cánula binasal", 2: "CPAP", 3: "Intubación endotraqueal", 4: "Bolsa y máscara"}),
  d=dict(rotulo="Reanimación en el primer minuto de vida", intro="Se revisa la frecuencia cardíaca cada 30 segundos.",
         pasos=[("0-30 s", "Pasos iniciales", "Calor, secar, estimular, vía aérea", False),
                ("30-60 s", "Ventilar", "Bolsa y máscara si apnea o FC < 100", True),
                ("+ 30 s", "Si FC < 60", "Compresiones 3:1 + intubar", False),
                ("+ 60 s", "Si sigue < 60", "Adrenalina IV + vía umbilical", False)],
         tag="ESTE CASO: FC 60 + apnea",
         veredicto=("Apnea + FC de 60 = ventilación con bolsa y máscara", "Compresiones solo si, tras 30 s de ventilación eficaz, la FC sigue < 60.")),
  escala=dict(nombre="Decisión por frecuencia cardíaca y respiración", que="Qué paso sigue en cada revisión del algoritmo de reanimación neonatal.",
              grados=[("Respira + FC ≥ 100", "Cuidados de rutina", ["Piel con piel", "Observar"]),
                      ("Apnea o FC < 100", "Ventilar", ["Bolsa y máscara", "Aire ambiente al inicio"]),
                      ("FC < 60 con ventilación", "Compresiones", ["3 compresiones : 1 ventilación", "Intubar, FiO₂ 100 %"]),
                      ("FC < 60 con compresiones", "Adrenalina", ["Vía IV o intraósea", "Revisar la ventilación"])],
              caso=1, porque=[("No hay respiración espontánea (apnea)", True), ("La FC de 60 está por debajo de 100", True),
                              ("Todavía no hubo 30 s de ventilación eficaz: sin compresiones", False)],
              conducta="Ventilar con bolsa y máscara y revisar la FC a los 30 segundos."))

